return 'wait';

/* Did the product selection take?
 *
 *  The card's data-state is one way Riot expresses it, but not the only one, and
 *  guessing its exact shape is what kept this flow stuck. The honest signal is
 *  the one the page itself gates on: REGISTER SELECTION goes from disabled to
 *  enabled once a product is chosen. Accept any of the three. */
function enabled(el){
  return !!el && !el.disabled && !el.hasAttribute('disabled') && el.getAttribute('aria-disabled') !== 'true';
}
function ticked(el){
  if (!el) return false;
  return el.checked === true
    || el.getAttribute('aria-checked') === 'true'
    || el.getAttribute('aria-pressed') === 'true'
    || el.getAttribute('data-state') === 'checked'
    || el.getAttribute('data-state') === 'selected';
}
for (var i = 0; i < 12; i++) {
  if (document.querySelector('[data-testid="product-selection-card"][data-state="selected"]')) return '1';
  var card = document.querySelector('[data-testid="product-selection-card"]');
  if (card) {
    var controls = card.querySelectorAll('button, input[type="checkbox"], [role="checkbox"]');
    for (var c = 0; c < controls.length; c++) if (ticked(controls[c])) return '1';
  }
  if (enabled(document.querySelector('[data-testid="register-cta"]'))) return '1';
  await new Promise(function (r) { setTimeout(r, 300); });
}
return '0';

/* Ready to submit the entry?
 *
 *  Riot gates REGISTER SELECTION itself: it stays disabled until a product is
 *  selected AND the terms are accepted. So that button's enabled state is the
 *  whole answer, and it does not depend on guessing how the card or the terms
 *  control express their own state.
 *
 *  The terms control is <button id="legal_checkbox">, not an input, so a
 *  .checked read never worked on it. */
function sleep(ms){return new Promise(function(r){setTimeout(r,ms);});}
function enabled(el){
  return !!el && !el.disabled && !el.hasAttribute('disabled') && el.getAttribute('aria-disabled') !== 'true';
}
for (var i = 0; i < 15; i++) {
  if (enabled(document.querySelector('[data-testid="register-cta"]'))) return '1';
  await sleep(400);
}
// Not ready. Say WHICH half is missing so the retry has something to act on
// instead of just counting attempts.
var legal = document.querySelector('#legal_checkbox, [data-testid="legal-agreement-checkbox"]');
var legalOn = !!legal && (legal.checked === true
  || legal.getAttribute('aria-checked') === 'true'
  || legal.getAttribute('aria-pressed') === 'true'
  || legal.getAttribute('data-state') === 'checked');
var card = !!document.querySelector('[data-testid="product-selection-card"][data-state="selected"]');
return '0:product=' + (card ? 'selected' : 'no') + ',terms=' + (legalOn ? 'accepted' : 'no');

